SourceCode.Declaration:
using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

/// <summary>
/// Core service responsible for authenticating with Salesforce OAuth2, validating B2C customer eligibility
/// (including v1.6 out-of-scope group transitions), constructing the CustomersV3 JSON payload (with composite
/// UTC timestamps, marketing consent, alias accounts, and UTF-8/Arabic support), and pushing single or batched
/// (up to 200) customer records to the Salesforce Apex REST v1.6 endpoint.
/// </summary>
public class UTCSFCustomerPushService
{
    private const str TargetCompanyId          = 'utc';
    private const str PartyTypePerson          = 'Person';
    private const int MaxCustomersPerBatchCall = 200;
    private const int TokenLifetimeMinutes     = 120;
    private const int TokenRefreshBufferMinutes = 5;

    private HttpClient httpClientInstance;
    private int        configuredTimeoutSeconds;

}

Method.Source:
public static UTCSFCustomerPushService construct()
{
    return new UTCSFCustomerPushService();
}

/// <summary>
/// Disposes the underlying <c>System.Net.Http.HttpClient</c> owned by this service instance
/// to prevent socket exhaustion across short-lived <c>Global::runAsync</c> sessions.
/// </summary>
public void dispose()
{
    if (httpClientInstance != null)
    {
        httpClientInstance.Dispose();
        httpClientInstance       = null;
        configuredTimeoutSeconds = 0;
    }
}

/// <summary>
/// Returns an <c>System.Net.Http.HttpClient</c> scoped to this service instance (reused across
/// batch iterations and disposed via <c>dispose()</c>) with TLS 1.2 enabled.
/// </summary>
/// <param name = "_timeoutSeconds">Request timeout in seconds.</param>
/// <returns>Configured <c>HttpClient</c> instance.</returns>
private HttpClient getHttpClient(int _timeoutSeconds = 30)
{
    ServicePointManager::SecurityProtocol = SecurityProtocolType::Tls12;

    int timeoutSec = _timeoutSeconds > 0 ? _timeoutSeconds : 30;

    if (httpClientInstance == null || configuredTimeoutSeconds != timeoutSec)
    {
        if (httpClientInstance != null)
        {
            httpClientInstance.Dispose();
        }

        httpClientInstance         = new HttpClient();
        httpClientInstance.Timeout = System.TimeSpan::FromSeconds(timeoutSec);
        configuredTimeoutSeconds   = timeoutSec;
    }

    return httpClientInstance;
}

/// <summary>
/// Retrieves a valid OAuth2 Bearer access token for Salesforce.
/// Returns the encrypted cached token from <c>UTCSFIntegrationParameters</c> if it has not expired;
/// otherwise requests a new token via the OAuth2 <c>client_credentials</c> grant and caches it for 120 minutes.
/// </summary>
/// <param name = "_forceRefresh">If true, bypasses the cached token and acquires a fresh token from Salesforce.</param>
/// <returns>OAuth2 Bearer access token string.</returns>
public str getAccessToken(boolean _forceRefresh = false)
{
    UTCSFIntegrationParameters parameters;

    changecompany(TargetCompanyId)
    {
        parameters = UTCSFIntegrationParameters::find();
    }

    str clientSecret = parameters.getClientSecret();
    if (!parameters.TokenUrl || !parameters.ClientId || !clientSecret)
    {
        throw error('Salesforce Integration Parameters (TokenUrl, ClientId, ClientSecret) are not configured.');
    }

    utcdatetime nowUtc      = DateTimeUtil::utcNow();
    utcdatetime safeExpiry  = DateTimeUtil::addMinutes(nowUtc, TokenRefreshBufferMinutes);
    str         cachedToken = parameters.getCachedAccessToken();

    if (!_forceRefresh
        && cachedToken != ''
        && parameters.TokenExpiresAt > safeExpiry)
    {
        return cachedToken;
    }

    HttpClient httpClient = this.getHttpClient(parameters.HttpTimeoutSeconds);

    str trimmedClientId = strLRTrim(parameters.ClientId);
    str formBody = strFmt(
        'grant_type=client_credentials&client_id=%1&client_secret=%2',
        System.Uri::EscapeDataString(trimmedClientId),
        System.Uri::EscapeDataString(clientSecret));

    str responseBody;
    int httpStatus;

    using (HttpRequestMessage requestMessage = new HttpRequestMessage(new HttpMethod('POST'), strLRTrim(parameters.TokenUrl)))
    {
        using (StringContent content = new StringContent(formBody, Encoding::UTF8, 'application/x-www-form-urlencoded'))
        {
            HttpContentHeaders contentHeaders = content.Headers;
            contentHeaders.ContentType = new MediaTypeHeaderValue('application/x-www-form-urlencoded');
            requestMessage.Content = content;

            using (HttpResponseMessage responseMessage = httpClient.SendAsync(requestMessage).GetAwaiter().GetResult())
            {
                responseBody = responseMessage.Content.ReadAsStringAsync().GetAwaiter().GetResult();
                httpStatus   = System.Convert::ToInt32(responseMessage.StatusCode);
            }
        }
    }

    if (httpStatus < 200 || httpStatus >= 300)
    {
        throw error(strFmt(
            'Salesforce OAuth2 token acquisition failed with HTTP %1 (ClientId len=%3, ClientSecret len=%4): %2',
            httpStatus,
            responseBody,
            strLen(trimmedClientId),
            strLen(clientSecret)));
    }

    JObject tokenJson   = JObject::Parse(responseBody);
    JToken  accessToken = tokenJson.GetValue('access_token');

    if (accessToken == null || System.String::IsNullOrWhiteSpace(accessToken.ToString()))
    {
        throw error('Salesforce OAuth2 response did not contain an access_token.');
    }

    str         tokenValue = accessToken.ToString();
    utcdatetime expiresAt  = DateTimeUtil::addMinutes(DateTimeUtil::utcNow(), TokenLifetimeMinutes);

    changecompany(TargetCompanyId)
    {
        UTCSFIntegrationParameters::updateCachedToken(tokenValue, expiresAt);
    }

    return tokenValue;
}

/// <summary>
/// Checks whether the supplied <c>CustGroupId</c> belongs to the configured v1.6 in-scope B2C groups
/// (default: <c>Retail, B2C E-Comm, Service, Staff</c>).
/// </summary>
public boolean isInScopeCustomerGroup(CustGroupId _custGroup)
{
    str targetGroup = strLwr(strLRTrim(_custGroup));
    if (targetGroup == '')
    {
        return false;
    }

    UTCSFIntegrationParameters parameters;
    changecompany(TargetCompanyId)
    {
        parameters = UTCSFIntegrationParameters::find();
    }

    str            groupsCsv  = parameters.effectiveInScopeCustomerGroups();
    List           groupList  = strSplit(groupsCsv, ',');
    ListEnumerator enumerator = groupList.getEnumerator();

    while (enumerator.moveNext())
    {
        str candidate = strLwr(strLRTrim(enumerator.current()));
        if (candidate != '' && candidate == targetGroup)
        {
            return true;
        }
    }

    return false;
}

/// <summary>
/// Validates base B2C Person requirements independent of Customer Group:
/// 1. <c>dataAreaId == "utc"</c>
/// 2. <c>PartyType == "Person"</c> (skip <c>Organization</c>)
/// 3. At least one of <c>PersonFirstName</c> or <c>PersonLastName</c> is populated.
/// </summary>
public boolean hasBasePersonEligibility(CustTable _custTable)
{
    if (!_custTable.RecId || !_custTable.AccountNum || !_custTable.Party)
    {
        return false;
    }

    if (strLwr(_custTable.DataAreaId) != TargetCompanyId)
    {
        return false;
    }

    DirPerson dirPerson = DirPerson::find(_custTable.Party);
    if (!dirPerson.RecId)
    {
        return false;
    }

    DirPersonName dirPersonName = DirPersonName::find(dirPerson.RecId);
    if (strLRTrim(dirPersonName.FirstName) == '' && strLRTrim(dirPersonName.LastName) == '')
    {
        return false;
    }

    return true;
}

/// <summary>
/// Evaluates pre-flight filtering rules to determine whether a <c>CustTable</c> record should be pushed to Salesforce.
/// Per Salesforce v1.6, a customer is eligible if they satisfy base Person rules AND either:
/// - Currently belong to an in-scope B2C group (<c>Retail</c>, <c>B2C E-Comm</c>, <c>Service</c>, <c>Staff</c>), OR
/// - Were previously synced to Salesforce and moved to an out-of-scope group (e.g. <c>Coops</c>) so Salesforce
///   can update their group and exclude them from marketing audiences.
/// </summary>
public boolean isEligibleCustomer(CustTable _custTable, boolean _allowSyncedOutOfScope = true)
{
    if (!this.hasBasePersonEligibility(_custTable))
    {
        return false;
    }

    if (this.isInScopeCustomerGroup(_custTable.CustGroup))
    {
        return true;
    }

    if (_allowSyncedOutOfScope)
    {
        boolean alreadySynced = false;
        changecompany(TargetCompanyId)
        {
            alreadySynced = UTCSFCustomerState::isCustomerSynced(_custTable.AccountNum);
        }
        if (alreadySynced)
        {
            return true;
        }
    }

    return false;
}

/// <summary>
/// Evaluates whether a queued customer item is eligible for outbound push, honoring the
/// <c>AllowOutOfScopeGroup</c> flag captured when a customer transitions from an in-scope group to an out-of-scope group.
/// </summary>
public boolean isEligibleQueueItem(CustTable _custTable, UTCSFCustomerPushQueue _queueRecord)
{
    if (!this.hasBasePersonEligibility(_custTable))
    {
        return false;
    }

    if (_queueRecord.AllowOutOfScopeGroup == NoYes::Yes)
    {
        return true;
    }

    return this.isEligibleCustomer(_custTable, true);
}

/// <summary>
/// Queries <c>CustomersV3</c> underlying tables and <c>UTCSFCustomerState</c> and builds the
/// Salesforce v1.6 Customer Push JSON payload for a single queue record.
/// </summary>
public str buildPayloadJson(UTCSFCustomerPushQueue _queueRecord)
{
    JObject rootObject     = new JObject();
    JArray  customersArray = new JArray();

    changecompany(TargetCompanyId)
    {
        CustTable custTable = CustTable::find(_queueRecord.CustAccount);
        if (!custTable.RecId)
        {
            throw error(strFmt('Customer %1 not found in company %2.', _queueRecord.CustAccount, TargetCompanyId));
        }

        JObject customerObj = this.buildCustomerJObject(custTable, _queueRecord);
        customersArray.Add(customerObj);
    }

    rootObject.Add('customers', customersArray);

    return rootObject.ToString(Formatting::None);
}

/// <summary>
/// Builds a batched JSON payload for up to 200 eligible queue records (mixing creates and updates).
/// </summary>
/// <param name = "_eligibleQueueRecords">List of validated <c>UTCSFCustomerPushQueue</c> records (max 200).</param>
/// <returns>Serialized UTF-8 JSON payload string containing the customers array.</returns>
public str buildBatchPayloadJson(List _eligibleQueueRecords)
{
    JObject        rootObject     = new JObject();
    JArray         customersArray = new JArray();
    ListEnumerator enumerator     = _eligibleQueueRecords.getEnumerator();

    changecompany(TargetCompanyId)
    {
        while (enumerator.moveNext())
        {
            UTCSFCustomerPushQueue queueRecord = enumerator.current();
            CustTable              custTable   = CustTable::find(queueRecord.CustAccount);

            if (custTable.RecId && this.isEligibleQueueItem(custTable, queueRecord))
            {
                customersArray.Add(this.buildCustomerJObject(custTable, queueRecord));
            }
        }
    }

    rootObject.Add('customers', customersArray);

    return rootObject.ToString(Formatting::None);
}

/// <summary>
/// Constructs a single customer <c>JObject</c> conforming to the Salesforce v1.6 Customer Push schema:
/// full current record, composite <c>ModifiedDateTimeCustTable</c>, marketing consent fields + timestamp,
/// and sibling <c>AliasCustomerAccounts</c> on the same Party.
/// </summary>
protected JObject buildCustomerJObject(CustTable _custTable, UTCSFCustomerPushQueue _queueRecord)
{
    DirPartyTable              dirPartyTable  = DirPartyTable::findRec(_custTable.Party);
    DirPerson                  dirPerson      = DirPerson::find(_custTable.Party);
    DirPersonName              dirPersonName  = DirPersonName::find(dirPerson.RecId);
    LogisticsElectronicAddress primaryPhone   = this.findPrimaryElectronicAddress(dirPartyTable, LogisticsElectronicAddressMethodType::Phone);
    LogisticsElectronicAddress primaryEmail   = this.findPrimaryElectronicAddress(dirPartyTable, LogisticsElectronicAddressMethodType::Email);
    LogisticsPostalAddress     primaryAddress = DirParty::primaryPostalAddress(_custTable.Party);
    UTCSFCustomerState         customerState  = UTCSFCustomerState::find(_custTable.AccountNum);

    // Leave blank when gender is unknown so Salesforce keeps Gender empty until populated (v1.6 Page 6)
    str genderStr = '';
    switch (dirPerson.Gender)
    {
        case Gender::Male:
            genderStr = 'Male';
            break;
        case Gender::Female:
            genderStr = 'Female';
            break;
        case Gender::NonSpecific:
            genderStr = 'NonSpecific';
            break;
        default:
            genderStr = '';
            break;
    }

    str onHoldStatusStr = 'No';
    switch (_custTable.Blocked)
    {
        case CustVendorBlocked::No:
            onHoldStatusStr = 'No';
            break;
        case CustVendorBlocked::Invoice:
            onHoldStatusStr = 'Invoice';
            break;
        case CustVendorBlocked::All:
            onHoldStatusStr = 'All';
            break;
        case CustVendorBlocked::Payment:
            onHoldStatusStr = 'Payment';
            break;
        case CustVendorBlocked::Requisition:
            onHoldStatusStr = 'Requisition';
            break;
        case CustVendorBlocked::Never:
            onHoldStatusStr = 'Never';
            break;
        default:
            onHoldStatusStr = 'No';
            break;
    }

    str phoneIsMobileStr = (primaryPhone.RecId != 0 && primaryPhone.IsMobilePhone == NoYes::Yes) ? 'Yes' : 'No';

    str sourceChannel       = _queueRecord.SourceChannel ? _queueRecord.SourceChannel : 'D365FO';
    str operatingUnitNumber = _queueRecord.OperatingUnitNumber ? _queueRecord.OperatingUnitNumber : '';
    str terminal            = _queueRecord.Terminal ? _queueRecord.Terminal : '';

    utcdatetime effectiveModifiedDateTime = this.resolveEffectiveModifiedDateTime(
        _custTable,
        dirPersonName,
        primaryAddress,
        customerState,
        _queueRecord);

    // Marketing consent fields (Salesforce v1.6 Area #4)
    boolean hasAnyConsent = (customerState.RecId != 0)
        && (customerState.ConsentSms      != UTCSFMarketingConsent::NotCaptured
         || customerState.ConsentWhatsApp != UTCSFMarketingConsent::NotCaptured
         || customerState.ConsentEmail    != UTCSFMarketingConsent::NotCaptured);

    JValue consentCapturedToken = (hasAnyConsent && customerState.ConsentCapturedDateTime != DateTimeUtil::minValue())
        ? new JValue(this.formatIso8601Utc(customerState.ConsentCapturedDateTime))
        : JValue::CreateNull();

    // Populate sibling D365 accounts sharing the same Party in 'utc' (Salesforce v1.6 Example F)
    JArray aliasAccountsArray = new JArray();
    if (_custTable.Party)
    {
        CustTable aliasCustTable;
        while select AccountNum from aliasCustTable
            order by CreatedDateTime asc, RecId asc
            where aliasCustTable.Party      == _custTable.Party
               && aliasCustTable.AccountNum != _custTable.AccountNum
        {
            aliasAccountsArray.Add(new JValue(aliasCustTable.AccountNum));
        }
    }

    JObject customerObj = new JObject();

    customerObj.Add('dataAreaId',                  new JValue(TargetCompanyId));
    customerObj.Add('CustomerAccount',             new JValue(_custTable.AccountNum));
    customerObj.Add('PartyNumber',                 new JValue(dirPartyTable.PartyNumber));
    customerObj.Add('PartyType',                   new JValue(PartyTypePerson));
    customerObj.Add('CustomerGroupId',             new JValue(_custTable.CustGroup));
    customerObj.Add('PersonFirstName',             new JValue(dirPersonName.FirstName ? dirPersonName.FirstName : ''));
    customerObj.Add('PersonMiddleName',            new JValue(dirPersonName.MiddleName ? dirPersonName.MiddleName : ''));
    customerObj.Add('PersonLastName',              new JValue(dirPersonName.LastName ? dirPersonName.LastName : ''));
    customerObj.Add('NameAlias',                   new JValue(dirPartyTable.NameAlias ? dirPartyTable.NameAlias : ''));
    customerObj.Add('PersonGender',                new JValue(genderStr));
    customerObj.Add('LanguageId',                  new JValue(dirPartyTable.LanguageId ? dirPartyTable.LanguageId : 'en-US'));
    customerObj.Add('PrimaryContactPhone',         new JValue(primaryPhone.Locator ? primaryPhone.Locator : ''));
    customerObj.Add('PrimaryContactPhoneIsMobile', new JValue(phoneIsMobileStr));
    customerObj.Add('PrimaryContactEmail',         new JValue(primaryEmail.Locator ? primaryEmail.Locator : ''));
    customerObj.Add('AddressCity',                 new JValue(primaryAddress.City ? primaryAddress.City : ''));
    customerObj.Add('AddressCountryRegionId',      new JValue(primaryAddress.CountryRegionId ? primaryAddress.CountryRegionId : ''));
    customerObj.Add('OnHoldStatus',                new JValue(onHoldStatusStr));
    customerObj.Add('CreatedDateTimeCustTable',    new JValue(this.formatIso8601Utc(_custTable.CreatedDateTime)));
    customerObj.Add('ModifiedDateTimeCustTable',   new JValue(this.formatIso8601Utc(effectiveModifiedDateTime)));
    customerObj.Add('SourceChannel',               new JValue(sourceChannel));
    customerObj.Add('OperatingUnitNumber',         new JValue(operatingUnitNumber));
    customerObj.Add('Terminal',                    new JValue(terminal));
    customerObj.Add('MarketingConsentSms',         this.consentEnumToJValue(customerState.ConsentSms));
    customerObj.Add('MarketingConsentWhatsApp',    this.consentEnumToJValue(customerState.ConsentWhatsApp));
    customerObj.Add('MarketingConsentEmail',       this.consentEnumToJValue(customerState.ConsentEmail));
    customerObj.Add('ConsentCapturedDateTime',     consentCapturedToken);
    customerObj.Add('AliasCustomerAccounts',       aliasAccountsArray);

    return customerObj;
}

private JValue consentEnumToJValue(UTCSFMarketingConsent _consent)
{
    switch (_consent)
    {
        case UTCSFMarketingConsent::Yes:
            return new JValue('Yes');
        case UTCSFMarketingConsent::No:
            return new JValue('No');
        default:
            return JValue::CreateNull();
    }
}

/// <summary>
/// Computes the latest UTC modification timestamp across <c>CustTable</c>, Global Address Book
/// ValidTimeState tables (<c>DirPersonName</c>, <c>LogisticsPostalAddress</c>), <c>UTCSFCustomerState</c>
/// consent timestamps, and the change queue event timestamp so GAB/consent updates always carry a newer
/// <c>ModifiedDateTimeCustTable</c> in Salesforce v1.6.
/// </summary>
private utcdatetime resolveEffectiveModifiedDateTime(
    CustTable              _custTable,
    DirPersonName          _dirPersonName,
    LogisticsPostalAddress _primaryAddress,
    UTCSFCustomerState     _customerState,
    UTCSFCustomerPushQueue _queueRecord)
{
    utcdatetime nowUtc  = DateTimeUtil::utcNow();
    utcdatetime bestUtc = _custTable.ModifiedDateTime;

    if (_custTable.CreatedDateTime > bestUtc)
    {
        bestUtc = _custTable.CreatedDateTime;
    }

    if (_dirPersonName.RecId && _dirPersonName.ValidFrom <= nowUtc && _dirPersonName.ValidFrom > bestUtc)
    {
        bestUtc = _dirPersonName.ValidFrom;
    }

    if (_primaryAddress.RecId && _primaryAddress.ValidFrom <= nowUtc && _primaryAddress.ValidFrom > bestUtc)
    {
        bestUtc = _primaryAddress.ValidFrom;
    }

    if (_customerState.RecId)
    {
        if (_customerState.ConsentCapturedDateTime <= nowUtc && _customerState.ConsentCapturedDateTime > bestUtc)
        {
            bestUtc = _customerState.ConsentCapturedDateTime;
        }
    }

    if (_queueRecord.CreatedDateTime > bestUtc)
    {
        bestUtc = _queueRecord.CreatedDateTime;
    }

    if (bestUtc == DateTimeUtil::minValue())
    {
        bestUtc = nowUtc;
    }

    return bestUtc;
}

/// <summary>
/// Resolves the primary <c>LogisticsElectronicAddress</c> for a party by method type (Phone or Email).
/// Checks <c>DirPartyTable.PrimaryContactPhone</c> / <c>PrimaryContactEmail</c> first, then falls back
/// to <c>DirPartyLocation</c> with <c>IsPrimary = Yes</c>.
/// </summary>
private LogisticsElectronicAddress findPrimaryElectronicAddress(
    DirPartyTable                        _dirPartyTable,
    LogisticsElectronicAddressMethodType _methodType)
{
    LogisticsElectronicAddress electronicAddress;

    if (!_dirPartyTable.RecId)
    {
        return electronicAddress;
    }

    if (_methodType == LogisticsElectronicAddressMethodType::Phone && _dirPartyTable.PrimaryContactPhone)
    {
        electronicAddress = LogisticsElectronicAddress::findRecId(_dirPartyTable.PrimaryContactPhone);
    }
    else if (_methodType == LogisticsElectronicAddressMethodType::Email && _dirPartyTable.PrimaryContactEmail)
    {
        electronicAddress = LogisticsElectronicAddress::findRecId(_dirPartyTable.PrimaryContactEmail);
    }

    if (!electronicAddress.RecId)
    {
        electronicAddress = DirParty::primaryElectronicAddress(_dirPartyTable.RecId, _methodType);
    }

    return electronicAddress;
}

/// <summary>
/// Formats a D365 <c>utcdatetime</c> value as an ISO-8601 UTC timestamp string (yyyy-MM-ddTHH:mm:ssZ).
/// </summary>
private str formatIso8601Utc(utcdatetime _dateTime)
{
    utcdatetime effectiveDateTime = (_dateTime == DateTimeUtil::minValue()) ? DateTimeUtil::utcNow() : _dateTime;
    str formatted = DateTimeUtil::toStr(effectiveDateTime);

    return strEndsWith(formatted, 'Z') ? formatted : (formatted + 'Z');
}

/// <summary>
/// Sends the outbound HTTP POST request to Salesforce for a single queue item, handles HTTP 401 token refresh,
/// parses Salesforce v1.6 row statuses (<c>created</c>, <c>updated</c>, <c>unchanged</c>, <c>skipped</c>,
/// <c>matched</c>, <c>merged</c>, <c>retry</c>, <c>error</c>) and <c>warnings</c>, updates
/// <c>UTCSFCustomerState</c>, <c>UTCSFCustomerPushLog</c>, and <c>UTCSFCustomerPushQueue</c>.
/// </summary>
public boolean pushCustomer(UTCSFCustomerPushQueue _queueRecord)
{
    if (!_queueRecord.RecId || !_queueRecord.CustAccount)
    {
        return false;
    }

    List singleItemList = new List(Types::Record);
    singleItemList.addEnd(_queueRecord);

    int succeededCount;
    int failedCount;

    [succeededCount, failedCount] = this.pushCustomerBatch(singleItemList);

    return succeededCount > 0 && failedCount == 0;
}

/// <summary>
/// Pushes 1 to 200 claimed <c>UTCSFCustomerPushQueue</c> records in a single HTTP POST call,
/// correlating each row in <c>results[]</c> back to its originating queue record via <c>index</c>.
/// </summary>
/// <param name = "_queueRecords">List of claimed <c>UTCSFCustomerPushQueue</c> records (up to 200).</param>
/// <returns>Container of <c>[int succeededCount, int failedCount]</c>.</returns>
public container pushCustomerBatch(List _queueRecords)
{
    if (_queueRecords == null || _queueRecords.empty())
    {
        return [0, 0];
    }

    UTCSFIntegrationParameters parameters;
    changecompany(TargetCompanyId)
    {
        parameters = UTCSFIntegrationParameters::find();
    }

    if (parameters.IsEnabled == NoYes::No)
    {
        changecompany(TargetCompanyId)
        {
            ListEnumerator disabledEnum = _queueRecords.getEnumerator();
            while (disabledEnum.moveNext())
            {
                UTCSFCustomerPushQueue disabledItem = disabledEnum.current();
                UTCSFCustomerPushQueue::resetToPending(disabledItem.RecId);
            }
        }
        return [0, 0];
    }

    Array eligibleQueueArray = new Array(Types::Record);
    Array eligibleCustArray  = new Array(Types::Record);
    Array eligiblePartyArray = new Array(Types::String);
    JArray customersJsonArray = new JArray();

    int eligibleCount = 0;
    int failedCount   = 0;
    int succeededCount = 0;

    changecompany(TargetCompanyId)
    {
        ListEnumerator candidateEnum = _queueRecords.getEnumerator();
        while (candidateEnum.moveNext())
        {
            UTCSFCustomerPushQueue queueItem = candidateEnum.current();
            if (!queueItem.RecId || !queueItem.CustAccount)
            {
                continue;
            }

            if (eligibleCount >= MaxCustomersPerBatchCall)
            {
                // Return any overflow beyond 200 back to Pending for the next chunk
                UTCSFCustomerPushQueue::resetToPending(queueItem.RecId);
                continue;
            }

            CustTable custTable = CustTable::find(queueItem.CustAccount);
            if (!this.isEligibleQueueItem(custTable, queueItem))
            {
                UTCSFCustomerPushQueue::markFailed(
                    queueItem.RecId,
                    strFmt('Customer %1 did not pass B2C eligibility filtering rules.', queueItem.CustAccount),
                    true);
                failedCount++;
                continue;
            }

            DirPartyTable dirPartyTable = DirPartyTable::findRec(custTable.Party);

            eligibleCount++;
            eligibleQueueArray.value(eligibleCount, queueItem);
            eligibleCustArray.value(eligibleCount, custTable);
            eligiblePartyArray.value(eligibleCount, dirPartyTable.PartyNumber);

            customersJsonArray.Add(this.buildCustomerJObject(custTable, queueItem));
        }
    }

    if (eligibleCount == 0)
    {
        return [0, failedCount];
    }

    JObject rootObject = new JObject();
    rootObject.Add('customers', customersJsonArray);

    str requestId       = strLwr(guid2StrWithoutBraces(newGuid()));
    str requestPayload  = rootObject.ToString(Formatting::None);
    str responsePayload = '';
    int httpStatus      = 0;
    int durationMs      = 0;

    System.Diagnostics.Stopwatch stopwatch = System.Diagnostics.Stopwatch::StartNew();

    try
    {
        str accessToken = this.getAccessToken(false);

        [httpStatus, responsePayload] = this.sendPostRequest(
            strLRTrim(parameters.ApiEndpointUrl),
            accessToken,
            requestId,
            requestPayload,
            parameters.HttpTimeoutSeconds);

        // Handle HTTP 401 Unauthorized: refresh cached token once and retry
        if (httpStatus == 401)
        {
            accessToken = this.getAccessToken(true);

            [httpStatus, responsePayload] = this.sendPostRequest(
                strLRTrim(parameters.ApiEndpointUrl),
                accessToken,
                requestId,
                requestPayload,
                parameters.HttpTimeoutSeconds);
        }

        stopwatch.Stop();
        durationMs = System.Convert::ToInt32(stopwatch.ElapsedMilliseconds);

        if (httpStatus < 200 || httpStatus >= 300)
        {
            // Whole-call HTTP failure (e.g. 400 invalid JSON/limit, 401 auth failure, 500 server error)
            boolean isCallPermanentFailure = (httpStatus >= 400
                && httpStatus < 500
                && httpStatus != 401
                && httpStatus != 408
                && httpStatus != 429);

            str httpErrorMsg = strFmt('HTTP %1: %2', httpStatus, responsePayload);

            changecompany(TargetCompanyId)
            {
                for (int idx = 1; idx <= eligibleCount; idx++)
                {
                    UTCSFCustomerPushQueue qItem     = eligibleQueueArray.value(idx);
                    str                    partyNum  = eligiblePartyArray.value(idx);

                    UTCSFCustomerPushLog::writeLog(
                        qItem.CustAccount,
                        partyNum,
                        requestId,
                        httpStatus,
                        UTCSFCustomerPushStatus::Failed,
                        '',
                        requestPayload,
                        responsePayload,
                        durationMs,
                        qItem.RecId);

                    UTCSFCustomerPushQueue::markFailed(qItem.RecId, httpErrorMsg, isCallPermanentFailure, requestId);
                    failedCount++;
                }
            }

            return [0, failedCount];
        }

        // Parse HTTP 2xx JSON response and correlate results[i] by index (0-based -> 1-based Array)
        Map rowResultsByOneBasedIdx = this.parseBatchResultsMap(responsePayload, eligibleCount);

        changecompany(TargetCompanyId)
        {
            for (int idx = 1; idx <= eligibleCount; idx++)
            {
                UTCSFCustomerPushQueue qItem     = eligibleQueueArray.value(idx);
                CustTable              cTable    = eligibleCustArray.value(idx);
                str                    partyNum  = eligiblePartyArray.value(idx);

                boolean rowSuccess          = false;
                boolean rowPermanentFailure = false;
                str     rowStatus           = '';
                str     matchedOn           = '';
                str     sfAccountId         = '';
                str     sfContactId         = '';
                str     warningsText        = '';
                str     errorsText          = '';

                if (rowResultsByOneBasedIdx.exists(idx))
                {
                    [rowSuccess, rowPermanentFailure, rowStatus, matchedOn, sfAccountId, sfContactId, warningsText, errorsText] =
                        rowResultsByOneBasedIdx.lookup(idx);
                }
                else
                {
                    rowSuccess          = false;
                    rowPermanentFailure = false;
                    errorsText          = strFmt('Missing result entry for row index %1 in Salesforce 2xx response.', idx - 1);
                }

                UTCSFCustomerPushStatus logSyncStatus;
                if (rowSuccess)
                {
                    logSyncStatus = (warningsText != '')
                        ? UTCSFCustomerPushStatus::SucceededWithWarnings
                        : UTCSFCustomerPushStatus::Succeeded;
                }
                else
                {
                    logSyncStatus = UTCSFCustomerPushStatus::Failed;
                }

                UTCSFCustomerPushLog::writeLog(
                    qItem.CustAccount,
                    partyNum,
                    requestId,
                    httpStatus,
                    logSyncStatus,
                    sfAccountId,
                    requestPayload,
                    responsePayload,
                    durationMs,
                    qItem.RecId,
                    rowStatus,
                    matchedOn,
                    sfContactId,
                    warningsText);

                if (rowSuccess)
                {
                    UTCSFCustomerPushQueue::markSucceeded(qItem.RecId, requestId, sfAccountId);

                    // Persist synced customer state unless a new out-of-scope customer was intentionally skipped
                    if (rowStatus != 'skipped' || sfAccountId != '')
                    {
                        UTCSFCustomerState::upsertSyncResult(
                            qItem.CustAccount,
                            partyNum,
                            cTable.CustGroup,
                            sfAccountId,
                            sfContactId,
                            rowStatus);
                    }

                    succeededCount++;
                }
                else
                {
                    UTCSFCustomerPushQueue::markFailed(qItem.RecId, errorsText, rowPermanentFailure, requestId);
                    failedCount++;
                }
            }
        }

        return [succeededCount, failedCount];
    }
    catch (Exception::CLRError)
    {
        stopwatch.Stop();
        durationMs = System.Convert::ToInt32(stopwatch.ElapsedMilliseconds);

        System.Exception clrException = CLRInterop::getLastException();
        str exceptionMessage = clrException != null ? clrException.ToString() : 'Unhandled CLR exception during Salesforce push.';

        changecompany(TargetCompanyId)
        {
            for (int idx = 1; idx <= eligibleCount; idx++)
            {
                UTCSFCustomerPushQueue qItem    = eligibleQueueArray.value(idx);
                str                    partyNum = eligiblePartyArray.value(idx);

                UTCSFCustomerPushLog::writeLog(
                    qItem.CustAccount,
                    partyNum,
                    requestId,
                    httpStatus,
                    UTCSFCustomerPushStatus::Failed,
                    '',
                    requestPayload,
                    exceptionMessage,
                    durationMs,
                    qItem.RecId);

                UTCSFCustomerPushQueue::markFailed(qItem.RecId, exceptionMessage, (httpStatus == 400), requestId);
                failedCount++;
            }
        }

        return [0, failedCount];
    }
    catch
    {
        stopwatch.Stop();
        durationMs = System.Convert::ToInt32(stopwatch.ElapsedMilliseconds);

        str infologError = infolog.text();

        changecompany(TargetCompanyId)
        {
            for (int idx = 1; idx <= eligibleCount; idx++)
            {
                UTCSFCustomerPushQueue qItem    = eligibleQueueArray.value(idx);
                str                    partyNum = eligiblePartyArray.value(idx);

                UTCSFCustomerPushLog::writeLog(
                    qItem.CustAccount,
                    partyNum,
                    requestId,
                    httpStatus,
                    UTCSFCustomerPushStatus::Failed,
                    '',
                    requestPayload,
                    infologError,
                    durationMs,
                    qItem.RecId);

                UTCSFCustomerPushQueue::markFailed(qItem.RecId, infologError, (httpStatus == 400), requestId);
                failedCount++;
            }
        }

        return [0, failedCount];
    }
}

/// <summary>
/// Executes the raw HTTP POST request to the Salesforce Customer Push endpoint with required headers:
/// - Authorization: Bearer &lt;access_token&gt;
/// - Content-Type: application/json; charset=utf-8
/// - X-Request-Id: &lt;unique-D365-GUID&gt;
/// </summary>
private container sendPostRequest(
    str _endpointUrl,
    str _accessToken,
    str _requestId,
    str _jsonPayload,
    int _timeoutSeconds = 30)
{
    if (!_endpointUrl)
    {
        throw error('Salesforce Customer Push Endpoint URL is not configured.');
    }

    HttpClient httpClient = this.getHttpClient(_timeoutSeconds);
    str        responseBody;
    int        httpStatus;

    using (HttpRequestMessage requestMessage = new HttpRequestMessage(new HttpMethod('POST'), _endpointUrl))
    {
        HttpRequestHeaders headers = requestMessage.Headers;
        headers.Authorization = new AuthenticationHeaderValue('Bearer', _accessToken);
        headers.Add('X-Request-Id', _requestId);

        // Encoding::UTF8 with media type "application/json" sets "Content-Type: application/json; charset=utf-8"
        using (StringContent content = new StringContent(_jsonPayload, Encoding::UTF8, 'application/json'))
        {
            requestMessage.Content = content;

            using (HttpResponseMessage responseMessage = httpClient.SendAsync(requestMessage).GetAwaiter().GetResult())
            {
                responseBody = responseMessage.Content.ReadAsStringAsync().GetAwaiter().GetResult();
                httpStatus   = System.Convert::ToInt32(responseMessage.StatusCode);
            }
        }
    }

    return [httpStatus, responseBody];
}

/// <summary>
/// Calls the Salesforce Health Check endpoint (HTTP GET with Bearer token) to verify connectivity and credentials.
/// Automatically refreshes the token once on HTTP 401.
/// </summary>
/// <returns>Container with [boolean isHealthy, int httpStatus, str responseBody].</returns>
public container checkHealth()
{
    UTCSFIntegrationParameters parameters;

    changecompany(TargetCompanyId)
    {
        parameters = UTCSFIntegrationParameters::find();
    }

    if (!parameters.ApiEndpointUrl)
    {
        throw error('Salesforce Customer Push Endpoint URL is not configured.');
    }

    str accessToken = this.getAccessToken(false);
    str requestId   = strLwr(guid2StrWithoutBraces(newGuid()));

    int httpStatus;
    str responseBody;

    [httpStatus, responseBody] = this.sendGetRequest(
        strLRTrim(parameters.ApiEndpointUrl),
        accessToken,
        requestId,
        parameters.HttpTimeoutSeconds);

    if (httpStatus == 401)
    {
        accessToken = this.getAccessToken(true);
        [httpStatus, responseBody] = this.sendGetRequest(
            strLRTrim(parameters.ApiEndpointUrl),
            accessToken,
            requestId,
            parameters.HttpTimeoutSeconds);
    }

    boolean isHealthy = (httpStatus >= 200 && httpStatus < 300);

    return [isHealthy, httpStatus, responseBody];
}

/// <summary>
/// Sends an HTTP GET request with Bearer authorization and X-Request-Id header.
/// </summary>
private container sendGetRequest(
    str _endpointUrl,
    str _accessToken,
    str _requestId,
    int _timeoutSeconds = 30)
{
    HttpClient httpClient = this.getHttpClient(_timeoutSeconds);
    str        responseBody;
    int        httpStatus;

    using (HttpRequestMessage requestMessage = new HttpRequestMessage(new HttpMethod('GET'), _endpointUrl))
    {
        HttpRequestHeaders headers = requestMessage.Headers;
        headers.Authorization = new AuthenticationHeaderValue('Bearer', _accessToken);
        headers.Add('X-Request-Id', _requestId);

        using (HttpResponseMessage responseMessage = httpClient.SendAsync(requestMessage).GetAwaiter().GetResult())
        {
            responseBody = responseMessage.Content.ReadAsStringAsync().GetAwaiter().GetResult();
            httpStatus   = System.Convert::ToInt32(responseMessage.StatusCode);
        }
    }

    return [httpStatus, responseBody];
}

/// <summary>
/// Parses the Salesforce v1.6 JSON response and maps each element of <c>results[]</c> to its 1-based
/// queue position (using <c>results[i].index + 1</c>, or positional fallback).
/// Each map entry holds:
/// <c>[boolean isSuccess, boolean isPermanentFailure, str rowStatus, str matchedOn, str sfAccountId, str sfContactId, str warningsText, str errorsText]</c>.
/// </summary>
protected Map parseBatchResultsMap(str _responsePayload, int _expectedCount)
{
    Map resultsByOneBasedIdx = new Map(Types::Integer, Types::Container);

    if (!_responsePayload)
    {
        for (int idx = 1; idx <= _expectedCount; idx++)
        {
            resultsByOneBasedIdx.insert(idx, [false, false, '', '', '', '', '', 'Empty 2xx response body from Salesforce.']);
        }
        return resultsByOneBasedIdx;
    }

    try
    {
        JObject responseJson = JObject::Parse(_responsePayload);
        JToken  resultsToken = responseJson.GetValue('results');

        if (resultsToken != null && resultsToken.Type == JTokenType::Array)
        {
            JArray resultsArray = resultsToken as JArray;
            int    arrayCount   = resultsArray != null ? resultsArray.Count : 0;

            for (int i = 0; i < arrayCount; i++)
            {
                JObject itemObj = resultsArray.get_Item(i) as JObject;
                if (itemObj == null)
                {
                    continue;
                }

                int zeroBasedIndex = i;
                JToken indexToken = itemObj.GetValue('index');
                if (indexToken != null && indexToken.Type == JTokenType::Integer)
                {
                    zeroBasedIndex = System.Convert::ToInt32(indexToken);
                }

                int oneBasedIdx = zeroBasedIndex + 1;
                resultsByOneBasedIdx.insert(oneBasedIdx, this.parseSingleRowResult(itemObj));
            }
        }
        else if (_expectedCount == 1)
        {
            // Fallback for legacy single-object responses without a results[] wrapper
            resultsByOneBasedIdx.insert(1, this.parseSingleRowResult(responseJson));
        }
    }
    catch
    {
        str parseErr = strFmt('Unexpected non-JSON 2xx response from Salesforce: %1', subStr(_responsePayload, 1, 500));
        for (int idx = 1; idx <= _expectedCount; idx++)
        {
            resultsByOneBasedIdx.insert(idx, [false, false, '', '', '', '', '', parseErr]);
        }
    }

    return resultsByOneBasedIdx;
}

/// <summary>
/// Evaluates a single Salesforce v1.6 row result <c>JObject</c> according to the v1.6 specification:
/// - <c>created</c>, <c>updated</c>, <c>unchanged</c>, <c>skipped</c>, <c>matched</c>, <c>merged</c> -&gt; Success (log <c>warnings</c>)
/// - <c>retry</c> -&gt; Transient lock failure (<c>isPermanentFailure = false</c>, retry in batch)
/// - <c>error</c> -&gt; Permanent validation failure (<c>isPermanentFailure = true</c>, fix data in D365)
/// </summary>
private container parseSingleRowResult(JObject _itemObj)
{
    boolean isSuccess          = false;
    boolean isPermanentFailure = false;
    str     rowStatus          = '';
    str     matchedOn          = '';
    str     sfAccountId        = '';
    str     sfContactId        = '';
    str     warningsText       = '';
    str     errorsText         = '';

    JToken sfAccountToken = _itemObj.GetValue('salesforceAccountId');
    if (sfAccountToken == null)
    {
        sfAccountToken = _itemObj.GetValue('accountId');
    }
    if (sfAccountToken == null)
    {
        sfAccountToken = _itemObj.GetValue('id');
    }
    if (sfAccountToken != null && sfAccountToken.Type != JTokenType::Null)
    {
        sfAccountId = sfAccountToken.ToString();
    }

    JToken sfContactToken = _itemObj.GetValue('salesforcePersonContactId');
    if (sfContactToken == null)
    {
        sfContactToken = _itemObj.GetValue('personContactId');
    }
    if (sfContactToken != null && sfContactToken.Type != JTokenType::Null)
    {
        sfContactId = sfContactToken.ToString();
    }

    JToken matchedOnToken = _itemObj.GetValue('matchedOn');
    if (matchedOnToken != null && matchedOnToken.Type != JTokenType::Null)
    {
        matchedOn = matchedOnToken.ToString();
    }

    JToken statusToken = _itemObj.GetValue('status');
    if (statusToken != null && statusToken.Type != JTokenType::Null)
    {
        rowStatus = strLwr(strLRTrim(statusToken.ToString()));
    }

    warningsText = this.joinJsonTokenStrings(_itemObj.GetValue('warnings'));
    errorsText   = this.joinJsonTokenStrings(_itemObj.GetValue('errors'));

    if (errorsText == '')
    {
        JToken fallbackErr = _itemObj.GetValue('errorMessage');
        if (fallbackErr == null)
        {
            fallbackErr = _itemObj.GetValue('message');
        }
        if (fallbackErr != null && fallbackErr.Type != JTokenType::Null)
        {
            errorsText = fallbackErr.ToString();
        }
    }

    // Legacy fallback when status is absent but boolean success is present
    if (rowStatus == '')
    {
        JToken successToken = _itemObj.GetValue('success');
        if (successToken != null && successToken.Type == JTokenType::Boolean)
        {
            rowStatus = System.Convert::ToBoolean(successToken) ? 'created' : 'error';
        }
    }

    switch (rowStatus)
    {
        case 'created':
        case 'updated':
        case 'unchanged':
        case 'skipped':
        case 'merged':
            isSuccess          = true;
            isPermanentFailure = false;
            break;

        case 'matched':
            isSuccess          = true;
            isPermanentFailure = false;
            warningsText       = (warningsText != '')
                ? ('[Action Required: Merge duplicate Parties in D365] ' + warningsText)
                : '[Action Required: Merge duplicate Parties in D365] Another row in the same call matched the same Salesforce customer.';
            break;

        case 'retry':
            isSuccess          = false;
            isPermanentFailure = false;
            if (errorsText == '')
            {
                errorsText = 'Salesforce record lock (status: retry). Queued for retry.';
            }
            break;

        case 'error':
            isSuccess          = false;
            isPermanentFailure = true;
            if (errorsText == '')
            {
                errorsText = 'Row rejected by Salesforce validation (status: error).';
            }
            else
            {
                errorsText = '[Row Error] ' + errorsText;
            }
            break;

        default:
            isSuccess          = false;
            isPermanentFailure = false;
            errorsText         = strFmt('Unrecognized Salesforce row status "%1". %2', rowStatus, errorsText);
            break;
    }

    return [isSuccess, isPermanentFailure, rowStatus, matchedOn, sfAccountId, sfContactId, warningsText, errorsText];
}

private str joinJsonTokenStrings(JToken _token)
{
    if (_token == null || _token.Type == JTokenType::Null)
    {
        return '';
    }

    if (_token.Type == JTokenType::Array)
    {
        JArray tokenArray = _token as JArray;
        int    count      = tokenArray != null ? tokenArray.Count : 0;
        str    joined     = '';

        for (int i = 0; i < count; i++)
        {
            JToken elem = tokenArray.get_Item(i);
            if (elem != null && elem.Type != JTokenType::Null)
            {
                str itemText = strLRTrim(elem.ToString());
                if (itemText != '')
                {
                    joined = (joined == '') ? itemText : (joined + '; ' + itemText);
                }
            }
        }

        return joined;
    }

    return strLRTrim(_token.ToString());
}

/// <summary>
/// Backward-compatible wrapper returning <c>[boolean isSuccess, str salesforceAccountId, str errorMessage]</c>
/// for callers inspecting a single-customer response payload.
/// </summary>
protected container parseCustomerPushResponse(str _responsePayload)
{
    Map resultsMap = this.parseBatchResultsMap(_responsePayload, 1);
    if (resultsMap.exists(1))
    {
        boolean isSuccess;
        boolean isPermanentFailure;
        str     rowStatus;
        str     matchedOn;
        str     sfAccountId;
        str     sfContactId;
        str     warningsText;
        str     errorsText;

        [isSuccess, isPermanentFailure, rowStatus, matchedOn, sfAccountId, sfContactId, warningsText, errorsText] = resultsMap.lookup(1);
        return [isSuccess, sfAccountId, errorsText];
    }

    return [false, '', 'Unable to parse Salesforce response.'];
}
